import os,json,stat,subprocess; from pathlib import Path; q=Path("evidence://campaign"); s=json.loads((q/"scopes/heldout.json").read_text()); paths=[q/"locked/proof-readiness",q/"advisories"]; print("PATHS",[(str(p),str(p.resolve()),p.is_symlink()) for p in paths]);
for r in s["records"]:
 p=Path(r["root"]); print("ROOT",r["id"],str(p.resolve()),p.is_symlink());
 for args in (["rev-parse","HEAD","HEAD^{tree}"],["status","--porcelain=v1","--untracked-files=no"]):
  c=["git","--no-pager","-c","core.fsmonitor=false","-C",str(p)]+args; x=subprocess.run(c,capture_output=True,text=True); print("COMMAND",c,"EXIT",x.returncode,"OUT",x.stdout,"ERR",x.stderr);
 for f in r["production_files"]+r["immediate_caller_or_helper_files"]+r["configuration_files"]+r["test_or_requirement_files"]:
  t=p/f; st=t.lstat(); print(f,"bytes",st.st_size,"regular",stat.S_ISREG(st.st_mode),"symlink",t.is_symlink())

import os,json,stat,hashlib; from pathlib import Path; q=Path("evidence://campaign"); s=json.loads((q/"scopes/heldout.json").read_text());
for r in s["records"]:
 p=Path(r["root"]); entries=[];
 for f in sorted(r["production_files"]+r["immediate_caller_or_helper_files"]+r["configuration_files"]+r["test_or_requirement_files"]):
  t=p/f; assert all(not x.is_symlink() for x in [t,*t.parents]); st=t.lstat(); assert stat.S_ISREG(st.st_mode) and st.st_size<=262144; b=t.read_bytes(); entries.append([f,len(b),hashlib.sha256(b).hexdigest()]);
 print(r["id"],"named_files_sha256",hashlib.sha256(json.dumps(entries,separators=(",",":"),ensure_ascii=True).encode()).hexdigest(),"files",len(entries));
p=q/"advisories/heldout-a"; print("OUTPUT",str(p.resolve()),"exists",p.exists(),"no_symlink_components",all(not x.is_symlink() for x in [p,*p.parents]))

