import json,hashlib; from pathlib import Path; p=Path("evidence://campaign/advisories/heldout-a/RESULT.json"); r=json.loads(p.read_text()); assert len(r["canonical_artifacts"])==3;
for a in r["canonical_artifacts"]:
 b=Path(a["path"]).read_bytes(); assert len(b)==a["bytes"] and hashlib.sha256(b).hexdigest()==a["sha256"]; assert b"## Scope and evidence" in b and b"## Decisions" in b and b"## Actionable handoff" in b and b"## Review and limitations" in b; print(a["slot"],"hash/byte-count/headings match");
print("RESULT JSON parses; artifact metadata matches. Data-only check, not semantic validation.")
